After saving the variable values, I tested a query to the 2024 PUMS API for age (AGEP), person weight (PWGTP), and sex (SEX) in North Carolina. I then wrote response_to_tibble() to turn the API’s JSON response into a tibble. The first row of the response supplies the column names, and the remaining rows become observations. The test returned 114,270 rows with the three requested variables and a state column added by the API.
At this point, the columns are still stored as character strings. The next step is to convert age and weight to numeric values and use the saved 2024 variable descriptions to label sex as a factor.
3. Helpers for labels and commute times
The time variables contain codes for intervals, so we look up each code’s description in the saved .rds file and calculate the interval’s midpoint.

get_item_labels &lt;- function(variable_values) {
  items &lt;- variable_values$item

  if (is.null(items)) {
    return(setNames(character(), character()))
  }

  unlist(items, use.names = TRUE)
}

#Return seconds
time_label_to_seconds &lt;- function(label) {
  pattern &lt;- paste0(
    "(?i)^(\\d{1,2}):(\\d{2})\\s*([ap])\\.m\\.\\s+to\\s+",
    "(\\d{1,2}):(\\d{2})\\s*([ap])\\.m\\."
  )

  parts &lt;- regmatches(label, regexec(pattern, label, perl = TRUE))[[1]]

  if (length(parts) != 7) {
    return(NA_real_)
  }

  to_minutes &lt;- function(hour, minute, am_pm) {
    hour &lt;- as.integer(hour) %% 12
    if (tolower(am_pm) == "p") hour &lt;- hour + 12

    hour * 60 + as.integer(minute)
  }

  start &lt;- to_minutes(parts[2], parts[3], parts[4])
  end &lt;- to_minutes(parts[5], parts[6], parts[7])

  #An interval that crosses midnight.
  if (end &lt; start) end &lt;- end + 24 * 60

  midpoint_minutes &lt;- ((start + end) / 2) %% (24 * 60)
  midpoint_minutes * 60
}

parse_time_variable &lt;- function(codes, variable_values) {
  labels &lt;- get_item_labels(variable_values)

  midpoint_lookup &lt;- vapply(
    labels,
    time_label_to_seconds,
    numeric(1)
  )

  seconds &lt;- unname(midpoint_lookup[as.character(codes)])
  hms::as_hms(seconds)
}

parse_numeric_variable &lt;- function(codes, variable_values) {
  numbers &lt;- suppressWarnings(as.numeric(codes))
  labels &lt;- get_item_labels(variable_values)

  missing_codes &lt;- names(labels)[
    grepl("^N/A", labels, ignore.case = TRUE)
  ]

  numbers[as.character(codes) %in% missing_codes] &lt;- NA_real_
  numbers
}

parse_categorical_variable &lt;- function(codes, variable_values) {
  labels &lt;- get_item_labels(variable_values)

  if (length(labels) == 0) {
    return(factor(codes))
  }

  #Put numbered codes in numerical order rather than JSON order.
  label_order &lt;- order(
    suppressWarnings(as.numeric(names(labels))),
    names(labels),
    na.last = TRUE
  )
  labels &lt;- labels[label_order]

  factor(
    as.character(codes),
    levels = names(labels),
    labels = unname(labels)
  )
}


