The output shows that plot() is a generic function that uses UseMethod("plot") to choose a plotting method based on the object’s class. For example, R uses plot.function() for a function and plot.data.frame() for a data frame. The methods contain different code because functions and data frames need to be plotted differently. In the same way, since our data have the "census" class, we can create summary.census() and plot.census() methods that are designed specifically for the census data and account for the PWGTP weights.

Numeric summaries

summary.census &lt;- function(object,
                           numeric_vars = NULL,
                           categorical_vars = NULL) {

  if (!"PWGTP" %in% names(object)) {
    stop("The census tibble must contain PWGTP.")
  }

  time_vars &lt;- c("JWAP", "JWDP", "JWMNP")

  #Select all numeric variables except PWGTP, year, and the time variables
  if (is.null(numeric_vars)) {
    numeric_vars &lt;- names(object)[
      vapply(object, is.numeric, logical(1))
    ]

    numeric_vars &lt;- setdiff(
      numeric_vars,
      c("PWGTP", "year", time_vars)
    )
  }

  #Select all factor variables
  if (is.null(categorical_vars)) {
    categorical_vars &lt;- names(object)[
      vapply(object, is.factor, logical(1))
    ]

    #Treat year as categorical
    if ("year" %in% names(object)) {
      categorical_vars &lt;- union(categorical_vars, "year")
    }
  }

  #Check the requested variables exist
  missing_numeric &lt;- setdiff(numeric_vars, names(object))
  missing_categorical &lt;- setdiff(categorical_vars, names(object))

  if (length(missing_numeric) &gt; 0) {
    stop(
      "Numeric variable(s) not found: ",
      paste(missing_numeric, collapse = ", ")
    )
  }

  if (length(missing_categorical) &gt; 0) {
    stop(
      "Categorical variable(s) not found: ",
      paste(missing_categorical, collapse = ", ")
    )
  }

  weights &lt;- object$PWGTP

  #Calculate weighted means and standard deviations
  numeric_summary &lt;- lapply(numeric_vars, function(variable) {

    values &lt;- object[[variable]]
    complete &lt;- !is.na(values) & !is.na(weights)

    values_complete &lt;- values[complete]
    weights_complete &lt;- weights[complete]

    sample_mean &lt;- sum(
      values_complete * weights_complete
    ) / sum(weights_complete)

    sample_sd &lt;- sqrt(
      sum(
        values_complete^2 * weights_complete
      ) / sum(weights_complete) -
        sample_mean^2
    )

    list(
      mean = sample_mean,
      standard_deviation = sample_sd
    )
  })

  names(numeric_summary) &lt;- numeric_vars

  # Calculate weighted counts for categorical variables
  categorical_summary &lt;- lapply(categorical_vars, function(variable) {

    values &lt;- object[[variable]]
    complete &lt;- !is.na(values) & !is.na(weights)

    values_complete &lt;- factor(values[complete])
    weights_complete &lt;- weights[complete]

    counts &lt;- tapply(
      weights_complete,
      values_complete,
      sum
    )

    return(counts)
  })

  names(categorical_summary) &lt;- categorical_vars

  #Return the summaries as a named list
  list(
    numeric_summaries = numeric_summary,
